/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var logger = require( 'debug' );
var isTextAlignment = require( '@stdlib/plot/vega/base/assert/is-text-alignment' );
var isUndefined = require( '@stdlib/assert/is-undefined' );
var join = require( '@stdlib/array/base/join' );
var textAlignments = require( '@stdlib/plot/vega/base/text-alignments' );
var format = require( '@stdlib/string/format' );
var changeEvent = require( './../change_event.js' );
var prop = require( './properties.js' );


// VARIABLES //

var debug = logger( 'vega:axis:set:'+prop.name );


// MAIN //

/**
* Sets the horizontal text alignment of an axis title.
*
* ## Notes
*
* -   Providing `undefined` "unsets" the configured value.
* -   Setting the alignment overrides the default setting based on the current `titleAnchor` value.
*
* @private
* @param {(string|void)} value - input value
* @throws {TypeError} must be a valid alignment
* @returns {void}
*/
function set( value ) {
	if ( !isTextAlignment( value ) && !isUndefined( value ) ) {
		throw new TypeError( format( 'invalid assignment. `%s` must be one of the following: "%s". Value: `%s`.', prop.name, join( textAlignments(), '", "' ), value ) );
	}
	if ( value !== this[ prop.private ] ) {
		debug( 'Current value: %s. New value: %s.', this[ prop.private ], value );
		this[ prop.private ] = value;
		this.emit( 'change', changeEvent( prop.name ) );
	}
}


// EXPORTS //

module.exports = set;
